import{_ as o,a as t,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第一册：英语初阶 · Lesson 104 Too, very, enough","description":"学习 too/very/enough，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 104 Too, very, enough","description":"学习 too/very/enough，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 too/very/enough，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 103 The French test","link":"/life/english/new-concept/book-1/unit-05/lesson-103"},"next":{"text":"第一册：英语初阶 · Lesson 105 Full of mistakes","link":"/life/english/new-concept/book-1/unit-05/lesson-105"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 103 The French test","link":"/life/english/new-concept/book-1/unit-05/lesson-103"},"next":{"text":"第一册：英语初阶 · Lesson 105 Full of mistakes","link":"/life/english/new-concept/book-1/unit-05/lesson-105"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-05/lesson-104.md","filePath":"life/english/new-concept/book-1/unit-05/lesson-104.md"}'),i={name:"life/english/new-concept/book-1/unit-05/lesson-104.md"};function l(r,e,s,h,c,d){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="第一册-英语初阶-·-lesson-104-too-very-enough" tabindex="-1">第一册：英语初阶 · Lesson 104 Too, very, enough <a class="header-anchor" href="#第一册-英语初阶-·-lesson-104-too-very-enough" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 104 Too, very, enough&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-05/overview">单元 5</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-103">配套课 Lesson 103</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>评价难度和完成任务的能力 本课要掌握too/very/enough，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。本课将前一课的结构迁移到另一个例子；请先口头作答，再写出完整句子，不只替换单个单词。</p><p>本课为配套句型训练；先回顾相邻奇数课，再独立完成本页的原创练习。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>exam</td><td>/ɪɡˈzæm/</td><td>n.</td><td>考试</td><td>take an exam</td></tr><tr><td>difficult</td><td>/ˈdɪfɪkəlt/</td><td>adj.</td><td>困难的</td><td>a difficult task</td></tr><tr><td>enough</td><td>/ɪˈnʌf/</td><td>adv.</td><td>足够</td><td>clear enough</td></tr><tr><td>fail</td><td>/feɪl/</td><td>v.</td><td>未通过</td><td>fail a test</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>enough time — enough 位于名词前</li><li>easy enough — enough 位于形容词后</li></ul><h2 id="语法讲解-too-very-enough" tabindex="-1">语法讲解：too/very/enough <a class="header-anchor" href="#语法讲解-too-very-enough" aria-label="Permalink to &quot;语法讲解：too/very/enough&quot;">​</a></h2><p>very 只是加强程度，too 通常表示超过合适范围、带来困难；enough 表足够。enough 修饰形容词或副词时放后面，如 easy enough；修饰名词时放前面，如 enough time。too ... to ... 表太……而不能，形容词或副词后接不定式说明结果。不要把 very difficult 误解为一定无法完成。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>This suitcase is too heavy for me to lift.</p></blockquote><p>这个箱子太重了，我提不起来。</p><p>Too heavy 表超过能力范围；for me 指动作执行者，to lift 给出因太重而无法完成的动作。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>形容词后用 enough；不要写 enough clear。too heavy 表示超出能承受范围，不只是“很重”。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“This suitcase is too heavy for me to lift.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>This suitcase is too heavy for me to lift. The instructions are clear enough to follow.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“评价难度和完成任务的能力”写两至三句，再读给同伴听。至少使用一次too/very/enough，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Too heavy 表超过能力范围；for me 指动作执行者，to lift 给出因太重而无法完成的动作。 Clear 是表语，enough 放在形容词之后；to follow 说明足够清楚所能完成的活动。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选择 very/too：箱子重得提不起，It is ___ heavy to lift.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> too</p><p><strong>解析：</strong> 按本课规则判断：very 只是加强程度，too 通常表示超过合适范围、带来困难；enough 表足够。enough 修饰形容词或副词时放后面，如 easy enough；修饰名词时放前面，如 enough time。too ... to ... 表太……而不能，形容词或副词后接不定式说明结果。不要把 very difficult 误解为一定无法完成。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“这个箱子太重了，我提不起来。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> This suitcase is too heavy for me to lift.</p><p><strong>解析：</strong> Too heavy 表超过能力范围；for me 指动作执行者，to lift 给出因太重而无法完成的动作。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：The instructions are clear enough to follow.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 这些说明足够清楚，可以照着操作。</p><p><strong>解析：</strong> Clear 是表语，enough 放在形容词之后；to follow 说明足够清楚所能完成的活动。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：too/very/enough。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-05/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-05/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-05/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-103">上一课</a> · <a href="/life/english/new-concept/book-1/unit-05/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-105">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const f=o(i,[["render",l]]);export{p as __pageData,f as default};
